/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var join = require( '@stdlib/array/base/join' );
var vega = require( './../globals/vega.js' );
var signalName = require( './../utils/signal_name.js' );
var log = require( './../log.js' );
var config = require( './../config.js' );


// MAIN //

/**
* Constructor for a visualization manager.
*
* @private
* @constructor
* @param {Object} state - state object
* @returns {Visualization} visualization instance
*/
function Visualization( state ) {
	if ( !( this instanceof Visualization ) ) {
		return new Visualization( state );
	}
	this._state = state;
	this._view = null;
	this._renderer = config.vega.renderer;
	return this;
}

/**
* Initializes a visualization.
*
* @name init
* @memberof Visualization.prototype
* @type {Function}
* @param {Callback} [clbk] - callback to invoke upon completion
*/
setReadOnly( Visualization.prototype, 'init', function init( clbk ) {
	var runtime;
	if ( this._view ) {
		this._view.finalize();
	}
	runtime = vega.parse( this._state.schema.transformed );
	this._view = new vega.View( runtime, {
		'logLevel': config.vega.logLevel,
		'renderer': this._renderer,
		'container': config.vega.container,
		'hover': true
	});

	log( 'Rendering visualization...' );
	this._view.runAsync()
		.then( onRender )
		.catch( onError );

	/**
	* Callback invoked upon rendering a visualization.
	*
	* @private
	* @returns {void}
	*/
	function onRender() {
		log( 'Successfully rendered visualization.' );
		if ( clbk ) {
			return clbk();
		}
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		console.error( 'Encountered an error when attempting to render visualization. Error: %s', error.message );
		if ( clbk ) {
			return clbk( error );
		}
	}
});

/**
* Callback invoked upon a new signal.
*
* @name onSignal
* @memberof Visualization.prototype
* @type {Function}
* @param {Array<string>} path - signal path
* @param {*} value - signal value
* @param {Callback} [clbk] - callback to invoke upon completion
* @returns {void}
*/
setReadOnly( Visualization.prototype, 'onSignal', function onSignal( path, value, clbk ) {
	var ns = path[ 0 ];

	// For height, width, padding, and certain axis property updates (e.g., aria, description, orient, and scale), we avoid propagating changes to the vega runtime, as these updates either require additional layout/scale modifications or full specification rebuilds and the logic for that resides on the server. Instead, these changes are pushed to the server, and the server will respond with a "refresh" event which will force the visualization to be re-rendered...
	if (
		ns === 'width' ||
		ns === 'height' ||
		ns === 'padding' ||
		( ns === 'axes' && ( path[ 2 ] === 'aria' || path[ 2 ] === 'description' || path[ 2 ] === 'orient' || path[ 2 ] === 'scale' ) )
	) {
		if ( clbk ) {
			return clbk();
		}
		return;
	}
	if ( ns === '' ) {
		path = path.slice( 1 );
	}
	try {
		this._view.signal( signalName( join( path, '/' ) ), value );
	} catch ( err ) {
		return onError( err );
	}
	this._view.runAsync()
		.then( onRender )
		.catch( onError );

	/**
	* Callback invoked upon rendering a visualization.
	*
	* @private
	* @returns {void}
	*/
	function onRender() {
		log( 'Successfully rendered visualization.' );
		if ( clbk ) {
			return clbk();
		}
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		console.error( 'Encountered an error when attempting to render visualization. Error: %s', error.message );
		if ( clbk ) {
			return clbk( error );
		}
	}
});


// EXPORTS //

module.exports = Visualization;
